import React, { useState } from "react";
import "./App.css";
import axios from "axios";
import InputForm from "./components/InputForm";
import ResultCard from "./components/ResultCard";



function App() {
  const [formData, setFormData] = useState({
    hs_avg: "",
    first_term_gpa: "",
    math_score: "",
    english_grade: ""
  });

  const [result, setResult] = useState(null);

  // Handle input change
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  // Handle submit (API call)
  const handleSubmit = async () => {
    try {
      const response = await axios.post(
        "http://localhost:5000/predict",
        {
          hs_avg: Number(formData.hs_avg),
          first_term_gpa: Number(formData.first_term_gpa),
          math_score: Number(formData.math_score),
          english_grade: Number(formData.english_grade)
        }
      );

      setResult(response.data);
    } catch (error) {
      console.error(error);
      alert("Backend not connected yet!");
    }
  };

  return (
  <div className="app">
    <div className="card">
      <h1>🎓 Student Success Predictor</h1>

      {/* Always show form */}
      <InputForm
        formData={formData}
        handleChange={handleChange}
        handleSubmit={handleSubmit}
      />


      {result && (
        <>
          <ResultCard result={result} />
          <Dashboard data={result} />
        </>
      )}
    </div>
  </div>
);
}

export default App;










